#!/bin/bash
# Uninstall script for Inkscape
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Inkscape..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Inkscape if running..."
pkill -f "Inkscape" 2>/dev/null || true

# Remove /Applications/Inkscape.app
echo "Removing /Applications/Inkscape.app..."
if [ -d "/Applications/Inkscape.app" ]; then
    rm -rf "/Applications/Inkscape.app" 2>/dev/null || true
elif [ -f "/Applications/Inkscape.app" ]; then
    rm -f "/Applications/Inkscape.app" 2>/dev/null || true
fi

# Remove $HOME/.config/inkscape
echo "Removing $HOME/.config/inkscape..."
if [ -d "$HOME/.config/inkscape" ]; then
    rm -rf "$HOME/.config/inkscape" 2>/dev/null || true
elif [ -f "$HOME/.config/inkscape" ]; then
    rm -f "$HOME/.config/inkscape" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Inkscape
echo "Removing $HOME/Library/Application Support/Inkscape..."
if [ -d "$HOME/Library/Application Support/Inkscape" ]; then
    rm -rf "$HOME/Library/Application Support/Inkscape" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Inkscape" ]; then
    rm -f "$HOME/Library/Application Support/Inkscape" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/org.inkscape.Inkscape
echo "Removing $HOME/Library/Application Support/org.inkscape.Inkscape..."
if [ -d "$HOME/Library/Application Support/org.inkscape.Inkscape" ]; then
    rm -rf "$HOME/Library/Application Support/org.inkscape.Inkscape" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/org.inkscape.Inkscape" ]; then
    rm -f "$HOME/Library/Application Support/org.inkscape.Inkscape" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/org.inkscape.Inkscape*
echo "Removing $HOME/Library/Caches/org.inkscape.Inkscape*..."
if [ -d "$HOME/Library/Caches/org.inkscape.Inkscape*" ]; then
    rm -rf "$HOME/Library/Caches/org.inkscape.Inkscape*" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/org.inkscape.Inkscape*" ]; then
    rm -f "$HOME/Library/Caches/org.inkscape.Inkscape*" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.inkscape.Inkscape.plist
echo "Removing $HOME/Library/Preferences/org.inkscape.Inkscape.plist..."
if [ -d "$HOME/Library/Preferences/org.inkscape.Inkscape.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.inkscape.Inkscape.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.inkscape.Inkscape.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.inkscape.Inkscape.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.inkscape.Inkscape.savedState
echo "Removing $HOME/Library/Saved Application State/org.inkscape.Inkscape.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.inkscape.Inkscape.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.inkscape.Inkscape.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.inkscape.Inkscape.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/org.inkscape.Inkscape.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
